function statusColor(s){ return STATUS_COLORS[s] || "#8B95A1"; }
function isOpenLike(s){
  if(!s) return false;
  return s.indexOf("ABIERTO")===0 || s.indexOf("EN PROCESO")===0 || s.indexOf("EN GESTION")===0 || s.indexOf("RE-APERTURA")===0;
}
function isClosedLike(s){ return s && s.indexOf("CERRADO")===0; }

let rawRows = [];
let charts = {};

function excelDateToISO(v){
  if(v===null||v===undefined||v==="") return null;
  if(v instanceof Date) return v.toISOString().slice(0,10);
  if(typeof v === "number"){
    const d = XLSX.SSF.parse_date_code(v);
    if(!d) return null;
    return `${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`;
  }
  if(typeof v === "string"){
    const d = new Date(v);
    if(!isNaN(d)) return d.toISOString().slice(0,10);
  }
  return null;
}

function normalizeRow(r){
  const out = {};
  for(const k in r){
    const key = k.trim ? k : k;
    const mapped = COLMAP[k] || COLMAP[String(k).trim()];
    if(mapped) out[mapped] = r[k];
  }
  ["fecha_auditoria","fecha_inicial","fecha_final"].forEach(f=>{
    if(out[f]!==undefined) out[f] = excelDateToISO(out[f]);
  });
  if(typeof out.estado === "string") out.estado = out.estado.trim();
  if(typeof out.pct_cumplimiento !== "number") out.pct_cumplimiento = null;
  if(typeof out.dias_cierre !== "number") out.dias_cierre = null;
  return out;
}

// Busca la fila donde realmente están los encabezados de columna (contiene "Establecimiento"),
// en vez de asumir una posición fija. Así el dashboard sigue funcionando aunque la plantilla
// cambie el número de filas de título/subtítulo antes de los datos.
function findHeaderRowIndex(ws){
  const ref = ws['!ref'];
  if(!ref) return 0;
  const range = XLSX.utils.decode_range(ref);
  const maxScanRow = Math.min(range.e.r, range.s.r + 15); // escanea hasta 16 filas
  for(let r = range.s.r; r <= maxScanRow; r++){
    for(let c = range.s.c; c <= range.e.c; c++){
      const cell = ws[XLSX.utils.encode_cell({r, c})];
      const v = cell && cell.v;
      if(typeof v === "string" && v.trim() === "Establecimiento") return r;
    }
  }
  return 0; // fallback: primera fila
}

function loadFromWorkbook(wb){
  if(!wb.SheetNames.includes(REQUIRED_SHEET)){
    setStatus(`No se encontró la hoja "${REQUIRED_SHEET}" en el archivo.`, true);
    return;
  }
  const ws = wb.Sheets[REQUIRED_SHEET];
  const headerRow = findHeaderRowIndex(ws);
  const json = XLSX.utils.sheet_to_json(ws, {range: headerRow, defval:null});
  const rows = json.map(normalizeRow).filter(r => r.establecimiento);
  if(rows.length === 0){
    setStatus(`No se encontraron hallazgos. Verifica que la hoja "${REQUIRED_SHEET}" tenga una columna "Establecimiento" con datos debajo.`, true);
    return;
  }
  rawRows = rows;
  setStatus(`Cargado: ${rows.length} hallazgos.`, false);
  buildFilterOptions();
  applyFilters();
}

function setStatus(msg, isErr){
  const el = document.getElementById('fileStatus');
  el.textContent = msg;
  el.style.color = isErr ? '#FFB4A8' : '#9FC2E0';
}

/* ============ FILE UPLOAD ============ */
document.getElementById('loadBtn').addEventListener('click', ()=> document.getElementById('fileInput').click());
document.getElementById('fileInput').addEventListener('change', function(e){
  const file = e.target.files[0];
  if(!file) return;
  document.getElementById('fileName').textContent = file.name;
  const reader = new FileReader();
  reader.onload = function(ev){
    try{
      const data = new Uint8Array(ev.target.result);
      const wb = XLSX.read(data, {type:"array", cellDates:true});
      loadFromWorkbook(wb);
    }catch(err){
      setStatus("Error al leer el archivo: " + err.message, true);
    }
  };
  reader.readAsArrayBuffer(file);
});

/* ============ FILTERS ============ */
const FILTER_FIELDS = [
  ["f_establecimiento","establecimiento"],
  ["f_ente","ente_auditor"],
  ["f_sub","subcomponente"],
  ["f_estado","estado"],
  ["f_plazo","plazo"],
  ["f_mes","mes"]
];

function buildFilterOptions(){
  FILTER_FIELDS.forEach(([elId, field])=>{
    const sel = document.getElementById(elId);
    const current = sel.value;
    const values = [...new Set(rawRows.map(r=>r[field]).filter(v=>v!==null && v!==undefined && v!==""))].sort();
    sel.innerHTML = '<option value="">Todos</option>' + values.map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');
    if(values.includes(current)) sel.value = current;
  });
}

FILTER_FIELDS.forEach(([elId])=>{
  document.getElementById(elId).addEventListener('change', applyFilters);
});
document.getElementById('clearFilters').addEventListener('click', ()=>{
  FILTER_FIELDS.forEach(([elId])=> document.getElementById(elId).value = "");
  applyFilters();
});

function getFiltered(){
  const active = FILTER_FIELDS.map(([elId, field])=>[field, document.getElementById(elId).value]).filter(([f,v])=>v);
  return rawRows.filter(r => active.every(([f,v]) => r[f] === v));
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

/* ============ RENDER ============ */
function applyFilters(){
  const rows = getFiltered();
  document.getElementById('filterCount').textContent = `${rows.length} de ${rawRows.length} hallazgos`;
  renderKPIs(rows);
  renderPulse(rows);
  renderCharts(rows);
  renderTable(rows);
}

function renderKPIs(rows){
  const total = rows.length;
  const cerrados = rows.filter(r=>isClosedLike(r.estado)).length;
  const abiertos = rows.filter(r=>isOpenLike(r.estado)).length;
  const pctCerrados = total ? Math.round(cerrados/total*100) : 0;
  const cumplValues = rows.map(r=>r.pct_cumplimiento).filter(v=>typeof v === 'number');
  const cumplProm = cumplValues.length ? Math.round(cumplValues.reduce((a,b)=>a+b,0)/cumplValues.length*100) : null;
  const diasValues = rows.map(r=>r.dias_cierre).filter(v=>typeof v === 'number');
  const diasProm = diasValues.length ? Math.round(diasValues.reduce((a,b)=>a+b,0)/diasValues.length) : null;
  const today = new Date().toISOString().slice(0,10);
  const vencidos = rows.filter(r => isOpenLike(r.estado) && r.fecha_final && r.fecha_final < today).length;

  const cards = [
    ["Total hallazgos", total, ""],
    ["% Cerrados", pctCerrados+"%", cerrados+" cerrados"],
    ["Abiertos / en proceso", abiertos, ""],
    ["Cumplimiento promedio", cumplProm!==null ? cumplProm+"%" : "s/d", cumplValues.length+" con dato"],
    ["Días promedio de cierre", diasProm!==null ? diasProm : "s/d", ""],
    ["Hallazgos vencidos", vencidos, "abiertos con plazo superado", vencidos>0]
  ];
  document.getElementById('kpiRow').innerHTML = cards.map(([label,val,sub,warn])=>`
    <div class="kpi-card ${warn?'warn':''}">
      <div class="bar"></div>
      <div class="kpi-label">${label}</div>
      <div class="kpi-value">${val}</div>
      <div class="kpi-sub">${sub||''}</div>
    </div>`).join('');
}

function renderPulse(rows){
  const total = rows.length || 1;
  const counts = {};
  rows.forEach(r=>{ const s = r.estado || "SIN ESTADO"; counts[s] = (counts[s]||0)+1; });
  const order = Object.keys(counts).sort((a,b)=>counts[b]-counts[a]);
  document.getElementById('pulseBar').innerHTML = order.map(s=>{
    const pct = (counts[s]/total*100);
    if(pct<0.5) return '';
    return `<div class="pulse-seg" style="width:${pct}%;background:${statusColor(s)}" title="${escapeHtml(s)}: ${counts[s]}">${pct>7?counts[s]:''}</div>`;
  }).join('');
  document.getElementById('pulseLegend').innerHTML = order.map(s=>
    `<span><span class="dot" style="background:${statusColor(s)}"></span>${escapeHtml(s)} (${counts[s]})</span>`
  ).join('');
}

const MES_ORDER = ["enero","febrero","marzo","abril","mayo","junio","julio","agosto","septiembre","octubre","noviembre","diciembre"];

function destroyChart(id){ if(charts[id]){ charts[id].destroy(); delete charts[id]; } }

function renderCharts(rows){
  // Tendencia mensual
  const mesesPresentes = MES_ORDER.filter(m => rows.some(r=>r.mes===m));
  const abiertosPorMes = mesesPresentes.map(m => rows.filter(r=>r.mes===m && isOpenLike(r.estado)).length);
  const cerradosPorMes = mesesPresentes.map(m => rows.filter(r=>r.mes===m && isClosedLike(r.estado)).length);
  destroyChart('trend');
  charts.trend = new Chart(document.getElementById('chartTrend'), {
    type:'line',
    data:{ labels: mesesPresentes.map(m=>m[0].toUpperCase()+m.slice(1)),
      datasets:[
        {label:'Cerrados', data:cerradosPorMes, borderColor:'#2E8B57', backgroundColor:'rgba(46,139,87,.12)', fill:true, tension:.3},
        {label:'Abiertos/En proceso', data:abiertosPorMes, borderColor:'#C0392B', backgroundColor:'rgba(192,57,43,.10)', fill:true, tension:.3}
      ]},
    options:{responsive:true,maintainAspectRatio:false, plugins:{legend:{position:'bottom',labels:{boxWidth:10,font:{size:11}}}}, scales:{y:{beginAtZero:true,ticks:{precision:0}}}}
  });

  // Estado
  const estados = [...new Set(rows.map(r=>r.estado).filter(Boolean))];
  const estadoCounts = estados.map(s=>rows.filter(r=>r.estado===s).length);
  destroyChart('estado');
  charts.estado = new Chart(document.getElementById('chartEstado'), {
    type:'doughnut',
    data:{ labels:estados, datasets:[{data:estadoCounts, backgroundColor:estados.map(statusColor), borderWidth:2, borderColor:'#fff'}] },
    options:{responsive:true,maintainAspectRatio:false, plugins:{legend:{position:'bottom',labels:{boxWidth:10,font:{size:10}}}}}
  });

  // Top establecimientos (abiertos)
  const estCounts = {};
  rows.filter(r=>isOpenLike(r.estado)).forEach(r=>{ estCounts[r.establecimiento]=(estCounts[r.establecimiento]||0)+1; });
  const estTop = Object.entries(estCounts).sort((a,b)=>b[1]-a[1]).slice(0,8);
  destroyChart('establecimiento');
  charts.establecimiento = new Chart(document.getElementById('chartEstablecimiento'), {
    type:'bar',
    data:{ labels:estTop.map(e=>e[0]), datasets:[{data:estTop.map(e=>e[1]), backgroundColor:'#2B5C8A', borderRadius:4}] },
    options:{indexAxis:'y', responsive:true, maintainAspectRatio:false, plugins:{legend:{display:false}}, scales:{x:{beginAtZero:true,ticks:{precision:0}}, y:{ticks:{font:{size:10.5}}}}}
  });

  // Top subcomponentes
  const subCounts = {};
  rows.forEach(r=>{ if(r.subcomponente) subCounts[r.subcomponente]=(subCounts[r.subcomponente]||0)+1; });
  const subTop = Object.entries(subCounts).sort((a,b)=>b[1]-a[1]).slice(0,8);
  destroyChart('subcomponente');
  charts.subcomponente = new Chart(document.getElementById('chartSubcomponente'), {
    type:'bar',
    data:{ labels:subTop.map(e=>e[0]), datasets:[{data:subTop.map(e=>e[1]), backgroundColor:'#0F8B8D', borderRadius:4}] },
    options:{indexAxis:'y', responsive:true, maintainAspectRatio:false, plugins:{legend:{display:false}}, scales:{x:{beginAtZero:true,ticks:{precision:0}}, y:{ticks:{font:{size:10.5}}}}}
  });

  // Plazo
  const plazos = ["CORTO PLAZO","MEDIANO PLAZO","LARGO PLAZO"].filter(p=>rows.some(r=>r.plazo===p));
  const plazoCounts = plazos.map(p=>rows.filter(r=>r.plazo===p).length);
  destroyChart('plazo');
  charts.plazo = new Chart(document.getElementById('chartPlazo'), {
    type:'bar',
    data:{ labels:plazos.map(p=>p.replace(' PLAZO','')), datasets:[{data:plazoCounts, backgroundColor:['#6E4FA1','#D68910','#2B5C8A'], borderRadius:4}] },
    options:{responsive:true, maintainAspectRatio:false, plugins:{legend:{display:false}}, scales:{y:{beginAtZero:true,ticks:{precision:0}}}}
  });
}

function renderTable(rows){
  document.getElementById('tableSub').textContent = `Mostrando ${Math.min(rows.length,300)} de ${rows.length} hallazgos filtrados · clic en una fila para ver el detalle`;
  const shown = rows.slice(0,300);
  document.getElementById('tableBody').innerHTML = shown.map((r,i)=>`
    <tr data-idx="${rows.indexOf(r)}">
      <td>${escapeHtml(r.establecimiento||'')}</td>
      <td class="mono">${r.fecha_auditoria||''}</td>
      <td>${escapeHtml(r.subcomponente||'')}</td>
      <td class="cell-trunc" title="${escapeHtml(r.hallazgo||'')}">${escapeHtml(r.hallazgo||'')}</td>
      <td>${escapeHtml(r.responsable||'')}</td>
      <td class="mono">${r.fecha_final||''}</td>
      <td><span class="badge" style="background:${statusColor(r.estado)}">${escapeHtml(r.estado||'s/d')}</span></td>
      <td class="mono">${r.dias_cierre ?? ''}</td>
    </tr>`).join('');
  document.querySelectorAll('#tableBody tr').forEach(tr=>{
    tr.addEventListener('click', ()=> openModal(rows[[...tr.parentNode.children].indexOf(tr)]));
  });
}

/* ============ MODAL ============ */
function openModal(r){
  document.getElementById('m_establecimiento').textContent = r.establecimiento || '';
  document.getElementById('m_meta').textContent = `${r.subcomponente||''} · ${r.ente_auditor||''} · Auditoría: ${r.fecha_auditoria||'s/d'} · Estado: ${r.estado||'s/d'}`;
  document.getElementById('m_hallazgo').textContent = r.hallazgo || '—';
  document.getElementById('m_causa').textContent = r.causa_raiz || '—';
  document.getElementById('m_que').textContent = r.accion_que || '—';
  document.getElementById('m_como').textContent = r.accion_como || '—';
  document.getElementById('m_responsable').textContent = r.responsable || '—';
  document.getElementById('m_indicador').textContent = r.indicador || '—';
  document.getElementById('m_evidencia').textContent = r.evidencia || '—';
  document.getElementById('m_obs').textContent = r.observaciones || '—';
  document.getElementById('modalBg').classList.add('open');
}
document.getElementById('modalClose').addEventListener('click', ()=> document.getElementById('modalBg').classList.remove('open'));
document.getElementById('modalBg').addEventListener('click', (e)=>{ if(e.target.id==='modalBg') e.currentTarget.classList.remove('open'); });

/* ============ INIT ============ */
rawRows = DEFAULT_DATA;
buildFilterOptions();
applyFilters();
setStatus(`Cargado: ${rawRows.length} hallazgos (archivo base).`, false);
